def totals(csv_text):
    results = {}
    for line in csv_text.splitlines():
        parts = line.split(",")
        if len(parts) < 2:
            continue
        name = parts[0].strip(",")
        amount = parts[1].strip()
        totals = results.setdefault(name, 0.0)
        totals += float(amount)
    return {name: round(total, 2) for name, total in results.items()}

